const RUBRIC={
modelo:{label:'Uso do modelo obrigatório e formato da entrega',max:1,levels:[{points:0,desc:'Não entrega o relatório em PDF no modelo obrigatório, ou apresenta o documento sem os dados de identificação solicitados.'},{points:1,desc:'Entrega o relatório em PDF no modelo obrigatório, com identificação preenchida e preservando estrutura e legibilidade.'}]},
demanda:{label:'Retomada do desafio e delimitação da demanda',max:1,levels:[{points:0,desc:'Não apresenta a pergunta-desafio iniciada por “Como podemos...”, ou não delimita suficientemente demanda, público, contexto ou resultado esperado.'},{points:1,desc:'Retoma a pergunta-desafio e delimita demanda específica e viável, explicando tarefa, público, contexto e resultado esperado com coerência.'}]},
configuracao:{label:'Registro da configuração, das fontes e do acesso ao Gem',max:2,levels:[{points:0,desc:'Não registra a configuração do Gem ou traz informações insuficientes para compreender o agente e a versão testada.'},{points:1,desc:'Registra parte da configuração, mas omite elementos relevantes das instruções, ferramenta, fontes, citações ou apresenta link ausente/inacessível.'},{points:2,desc:'Registra nome, descrição, instruções integrais, ferramenta, fontes e funções, citações justificadas, decisões relevantes e link público habilitado.'}]},
testagem:{label:'Testagem em situação realista e evidências da interação',max:2,levels:[{points:0,desc:'Não documenta teste ou as capturas não permitem ler solicitação e resposta.'},{points:1,desc:'Apresenta capturas legíveis, mas não explicita adequadamente objetivo/resultado esperado ou usa situação pouco relacionada à demanda.'},{points:2,desc:'Documenta teste significativo e realista, explicita objetivo e resposta satisfatória e apresenta capturas legíveis da solicitação e resposta.'}]},
analise:{label:'Análise crítica dos resultados e refinamento',max:2,levels:[{points:0,desc:'Não analisa os resultados ou apenas afirma que funcionou/não funcionou, sem discutir respostas ou ajustes.'},{points:1,desc:'Identifica aspectos positivos e melhorias, mas de modo genérico; ajustes são vagos ou pouco relacionados aos testes.'},{points:2,desc:'Analisa utilidade, qualidade, clareza, adequação e fontes; identifica falhas/lacunas e relaciona ajustes concretos aos testes.'}]},
contribuicao:{label:'Contribuição do agente para o desafio do portfólio',max:1,levels:[{points:0,desc:'Não explica a contribuição ou não delimita parte apoiada, beneficiários e limites.'},{points:1,desc:'Explica como o Gem contribui, qual parte apoia, quem se beneficia e os limites, sem exigir solução integral do desafio.'}]},
transparencia:{label:'Transparência sobre o uso de IA na elaboração do relatório',max:1,levels:[{points:0,desc:'Não responde, confunde o Gem com IA usada no relatório ou não explica ferramentas, finalidade e uso.'},{points:1,desc:'Declara claramente uso ou não uso de IA além do Gem e, se houve uso, identifica ferramentas, finalidade e forma de emprego.'}]}
};
const ORDER=Object.keys(RUBRIC);
const FIELD_IDS=['nome','matricula','orientador','conformidadeModelo','desafio','demanda','publicoContexto','resultadoEsperado','nomeGem','linkGem','linkVerificado','descricaoGem','instrucoesGem','ferramentaPadrao','fontesConhecimento','citacoesStatus','citacoes','outrasConfiguracoes','objetivoTeste','resultadoEsperadoTeste','evidenciasTeste','funcionouBem','precisaMelhorar','ajustes','contribuicao','iaDeclaracao','iaDescricao'];
let classes=[],evaluations=[],currentEvaluationId=null,authHeader=sessionStorage.getItem('p5Auth')||'',pdfImageCount=0,rawPdfPages=[],pagePreviews=[],annotatedLinks=[],structuredPageRows=[];
const $=id=>document.getElementById(id);
const value=id=>$(id)?.type==='checkbox'?($(id).checked?'Sim, verificado':'Não verificado'):($(id)?.value||'').trim();
const escapeHtml=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const slug=s=>String(s||'avaliacao').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,80)||`avaliacao-${Date.now()}`;

async function api(url,options={}){
  const headers={...(options.headers||{}),...(window.SeletorIA?SeletorIA.cabecalho():{})};
  if(authHeader) headers.Authorization=authHeader;
  if(options.body && !(options.body instanceof FormData)) headers['Content-Type']='application/json';
  let response=await fetch(url,{...options,headers});
  if(response.status===401&&response.headers.get('X-Login-Necessario')){
    const login=await SeletorIA.pedirLogin('professor'); if(!login) throw new Error('Autenticação cancelada.');
    authHeader=SeletorIA.basic(login.usuario,login.senha); sessionStorage.setItem('p5Auth',authHeader);
    response=await fetch(url,{...options,headers:{...headers,...SeletorIA.cabecalho(),Authorization:authHeader}});
    if(response.status===401){authHeader='';sessionStorage.removeItem('p5Auth');SeletorIA.esquecerLogin();throw new Error('Usuário ou senha incorretos.');}
  }
  const text=await response.text(); let data; try{data=JSON.parse(text);}catch{data={erro:text||`Erro ${response.status}`};}
  if(!response.ok) throw new Error(data.erro||`Erro ${response.status}`);
  return data;
}

function renderRubric(){
  $('rubric').innerHTML=ORDER.map(key=>{const c=RUBRIC[key];return `<fieldset><legend>${escapeHtml(c.label)} (0 a ${c.max} pt${c.max>1?'s':''})</legend>${c.levels.map(n=>`<label class="level"><input type="radio" name="rub_${key}" value="${n.points}"><span>${escapeHtml(n.desc)}</span><span class="pts">${n.points} pt${n.points===1?'':'s'}</span></label>`).join('')}<label>Observação do avaliador</label><textarea id="obs_${key}" placeholder="Evidência, ponto forte, ausência ou orientação personalizada."></textarea></fieldset>`}).join('');
  $('rubric').addEventListener('change',()=>{updateScore();generateLocalFeedback(false);});
  ORDER.forEach(k=>$(`obs_${k}`).addEventListener('input',()=>generateLocalFeedback(false)));
}
function selected(key){const el=document.querySelector(`input[name="rub_${key}"]:checked`);return el?Number(el.value):null;}
function setScore(key,points){const el=document.querySelector(`input[name="rub_${key}"][value="${points}"]`);if(el)el.checked=true;}
function total(){return ORDER.reduce((n,k)=>n+(selected(k)??0),0);}
function updateScore(){
  $('scoreTotal').textContent=total().toLocaleString('pt-BR',{maximumFractionDigits:1});
  $('scoreTable').innerHTML=ORDER.map(k=>{const c=RUBRIC[k],p=selected(k);const cls=p===null?'mid':p===c.max?'max':p===0?'zero':'mid';return `<tr><td>${escapeHtml(c.label)}</td><td style="text-align:right"><span class="badge ${cls}">${p===null?'—':`${p}/${c.max}`}</span></td></tr>`}).join('');
  renderAlerts();
}
function automaticAlerts(){
  const out=[];
  if(!value('nome'))out.push('Nome não preenchido.'); if(!value('matricula'))out.push('Matrícula não preenchida.'); if(!value('orientador'))out.push('Orientador(a) não informado(a).');
  if(!/^como podemos\b/i.test(value('desafio')))out.push('A pergunta-desafio não começa claramente com “Como podemos...”.');
  if(!value('demanda')||!value('publicoContexto')||!value('resultadoEsperado'))out.push('Demanda, público/contexto ou resultado esperado está ausente.');
  if(!value('instrucoesGem'))out.push('Instruções do Gem não registradas.'); if(!value('linkGem'))out.push('Link público do Gem não informado.'); else if(value('linkVerificado')==='Não foi possível acessar publicamente')out.push('Não foi possível acessar o agente publicamente pelo link informado.'); else if(!value('linkVerificado').startsWith('Sim'))out.push('O acesso público ao Gem ainda não foi testado pelo professor.');
  if(!value('evidenciasTeste'))out.push('Legibilidade e suficiência das evidências do teste ainda não foram registradas.');
  if(!value('funcionouBem')||!value('precisaMelhorar')||!value('ajustes'))out.push('Análise crítica ou refinamento está incompleto.');
  if(!value('iaDeclaracao'))out.push('Declaração de transparência sobre IA não respondida.'); if(ORDER.some(k=>selected(k)===null))out.push('Há critérios da rubrica ainda não avaliados.');
  return out;
}
function renderAlerts(){const manual=value('manualAlerts').split('\n').map(s=>s.trim()).filter(Boolean);const all=[...automaticAlerts(),...manual];$('alerts').innerHTML=all.length?all.map(a=>`<div class="alert">${escapeHtml(a)}</div>`).join(''):'<div class="ok">Nenhum alerta pendente.</div>';}
function generateLocalFeedback(overwrite=true){
  if(!overwrite && value('feedback'))return;
  const first=value('nome').split(/\s+/)[0]||'estudante'; const lines=[`Olá, ${first},`,`A avaliação da sua P5 resultou em ${total().toLocaleString('pt-BR')} de 10 pontos.`];
  for(const k of ORDER){const p=selected(k);if(p===null)continue;const obs=value(`obs_${k}`);lines.push(`${RUBRIC[k].label} (${p}/${RUBRIC[k].max}): ${obs||RUBRIC[k].levels.find(n=>n.points===p)?.desc||''}`);}
  const alerts=automaticAlerts().filter(a=>!a.includes('rubrica'));if(alerts.length)lines.push(`Para aprimorar a entrega, revise especialmente: ${alerts.join(' ')}`);
  lines.push('Um abraço,','Prof. Rogério');$('feedback').value=lines.join('\n\n');
}
function formData(){const d={};FIELD_IDS.forEach(id=>d[id]=value(id));d.pdfImageCount=pdfImageCount;return d;}

async function autoEvaluate(){
  const b=$('autoEvaluate');b.disabled=true;b.textContent='Analisando...';
  try{const r=await api('/api/avaliar',{method:'POST',body:JSON.stringify(formData())});let preenchidos=0;for(const k of ORDER){const x=r.pontuacoes?.[k];if(x&&Number.isFinite(Number(x.pontos))){setScore(k,Number(x.pontos));$(`obs_${k}`).value=x.justificativa||'';preenchidos++;}}if(preenchidos!==ORDER.length)throw new Error(`a resposta preencheu apenas ${preenchidos} de ${ORDER.length} critérios`);$('manualAlerts').value=(r.alertas||[]).join('\n');$('feedback').value=r.feedback||'';$('autoEvaluateStatus').textContent=r.modo==='local-fallback'?'A IA não concluiu a análise. A rubrica foi preenchida pela avaliação local conservadora; revise as notas e as capturas.':r.modo==='local'?'Avaliação automática local concluída. Revise as sugestões, especialmente as capturas.':'Avaliação com IA concluída. Revise as sugestões antes de salvar.';updateScore();}
  catch(e){$('autoEvaluateStatus').textContent=`Não foi possível avaliar: ${e.message}`;}finally{b.disabled=false;b.textContent='✨ Avaliar automaticamente';}
}
async function analyzeAgent(){const b=$('analyzeAgent');b.disabled=true;b.textContent='Analisando...';$('agentAnalysisStatus').textContent='';try{const r=await api('/api/analisar-agente',{method:'POST',body:JSON.stringify(formData())});const blocks=[r.parecer,r.pontosFortes?.length?`Pontos fortes\n• ${r.pontosFortes.join('\n• ')}`:'',r.riscosELacunas?.length?`Riscos e lacunas\n• ${r.riscosELacunas.join('\n• ')}`:'',r.sugestoesDeRefinamento?.length?`Sugestões de refinamento\n• ${r.sugestoesDeRefinamento.join('\n• ')}`:''];$('agentAnalysis').value=blocks.filter(Boolean).join('\n\n');$('agentAnalysisStatus').textContent=r.modo==='local'?'Análise complementar local concluída. Revise o parecer antes de utilizá-lo.':'Análise complementar com IA concluída.';}catch(e){$('agentAnalysisStatus').textContent=`Não foi possível analisar: ${e.message}`;}finally{b.disabled=false;b.textContent='Analisar concepção do agente';}}
function validExternalUrl(raw){try{const url=new URL(String(raw||'').trim());return ['http:','https:'].includes(url.protocol)?url:null;}catch{return null;}}
function openGem(){const url=validExternalUrl(value('linkGem'));if(!url){$('gemWindowStatus').textContent='Informe um link válido começando com https://.';$('linkGem').focus();return;}const win=window.open(url.href,'avaliadorP5Gem','popup=yes,width=1080,height=820,menubar=yes,toolbar=yes,location=yes,resizable=yes,scrollbars=yes');$('gemWindowStatus').textContent=win?'Agente aberto em uma janela separada. Converse com ele e, depois, confirme abaixo se o acesso público funcionou.':'O navegador bloqueou a janela. Autorize pop-ups para este aplicativo e tente novamente.';}

function normalizePdfText(s){return String(s||'').replace(/\s+fi\s+/gi,'fi').replace(/desa\s+fi\s+o/gi,'desafio').replace(/con\s+fi\s+gura/gi,'configura').replace(/satis\s+fatóri/gi,'satisfatóri').replace(/bene\s+fi\s+ci/gi,'benefici').replace(/identi\s+fi\s+c/gi,'identific');}
function cleanPdfText(s,{preserveLines=false}={}){let out=normalizePdfText(s).replace(/Especializa[cç][aã]o\s*lato\s*sensu[^\n]*/gi,' ').replace(/Instituto Federal de Santa Catarina[^\n]*/gi,' ').replace(/Rua:\s*14 de julho[^\n]*/gi,' ').replace(/Fone:\s*\(48\)[^\n]*/gi,' ').replace(/P5\s*-\s*PORTFÓLIO II/gi,' ').replace(/MEDIAÇÃO\s+COM\s+AGENTE\s+DE\s+IA/gi,' ').replace(/ESCREVA AQUI/gi,' ').replace(/COLE AQUI[^\n]*/gi,' ').replace(/SEU NOME/gi,' ').replace(/^\s*MATRÍCULA\s*$/gim,' ').replace(/^\s*selecione\s*$/gim,' ');return preserveLines?out.replace(/[ \t]+\n/g,'\n').replace(/\n[ \t]+/g,'\n').replace(/\n{3,}/g,'\n\n').trim():out.replace(/\s+/g,' ').trim();}
function between(text,start,end,options){const a=text.search(start);if(a<0)return'';const rest=text.slice(a);const sm=rest.match(start);const from=a+(sm?.index||0)+(sm?.[0]?.length||0);const tail=text.slice(from);const b=tail.search(end);return cleanPdfText(b<0?tail:tail.slice(0,b),options);}
function simpleMatch(text,re){const m=text.match(re);return cleanPdfText(m?.[1]||'');}
function layoutRows(content){const rows=[];for(const item of content.items){const x=item.transform[4],y=item.transform[5],width=item.width||0;let row=rows.find(r=>Math.abs(r.y-y)<2.2);if(!row){row={y,items:[]};rows.push(row);}row.items.push({x,width,text:item.str});}rows.sort((a,b)=>b.y-a.y);for(const row of rows)row.items.sort((a,b)=>a.x-b.x);return rows;}
function rowText(row){let line='',end=null;for(const item of row.items){if(end!==null){const gap=item.x-end;line+=gap>28?'\t':gap>2?' ':'';}line+=item.text;end=item.x+item.width;}return line.trimEnd();}
function textWithLayout(content){return layoutRows(content).map(rowText).join('\n');}
function extractKnowledgeTable(){let active=false,current=null;const records=[];const add=(key,text)=>{text=String(text||'').trim();if(text)current[key]+=(current[key]?' ':'')+text;};for(const rows of structuredPageRows){for(const row of rows){const text=rowText(row);if(/N[ºo]\s+Fonte\/arquivo/i.test(text)&&/Função no agente/i.test(text)){active=true;continue;}if(active&&/3\.6\s*Configurações/i.test(text)){active=false;break;}if(!active||/Especializa[cç][aã]o|Instituto Federal|Rua:\s*14|Fone:/i.test(text))continue;const numberItem=row.items.find(item=>item.x<110&&/^\d{1,2}$/.test(item.text.trim()));if(numberItem){current={n:numberItem.text.trim(),source:'',origin:'',role:''};records.push(current);}if(!current)continue;add('source',row.items.filter(i=>i.x>=110&&i.x<230).map(i=>i.text).join(' '));add('origin',row.items.filter(i=>i.x>=230&&i.x<344).map(i=>i.text).join(' '));add('role',row.items.filter(i=>i.x>=344).map(i=>i.text).join(' '));}}
  return records.map(r=>{let role=r.role.trim();const action=role.search(/\b(?:Fornecer|Impedir|Parametrizar|Balizar|Orientar|Apoiar|Permitir|Garantir|Ancorar)\b/i);if(action>0)role=role.slice(action);return normalizePdfText(`${r.n} | ${r.source.trim()} | ${r.origin.trim()} | ${role}`);}).join('\n');
}
function stripFormPrompt(text,patterns=[]){let out=String(text||'').trim();for(const re of patterns)out=out.replace(re,'').trim();return out;}
function formatTableRows(text){const structured=extractKnowledgeTable();if(structured)return structured;let table=stripFormPrompt(text,[/^Registre cada arquivo[\s\S]*?porque as escolheu\)?\s*/i,/^N[ºo]\s+Fonte\/arquivo\s+Origem e tipo\s+Função no agente\s*/i]);const matches=[...table.matchAll(/(?:^|\n)\s*(\d{1,2})\s+/g)];if(!matches.length)return table;return matches.map((m,i)=>{const start=m.index+m[0].length,end=i+1<matches.length?matches[i+1].index:table.length;return `${m[1]} | ${table.slice(start,end).trim().replace(/\t+/g,' | ').replace(/\n+/g,' ')}`;}).join('\n');}
function applyPreliminaryExtraction(text,fileName=''){
  let nome=simpleMatch(text,/Nome completo:\s*([^\n]+)/i);if(!nome){const m=String(fileName).match(/\(([^()]+)\)\s*\.pdf$/i);nome=m?.[1]?.trim()||'';}$('nome').value=nome;$('matricula').value=simpleMatch(text,/(?:Número de matrícula|Matrícula):\s*([^\n]+)/i);$('orientador').value=simpleMatch(text,/Orientador\(a\):\s*([^\n]+)/i);
  const secao1=between(text,/1\.\s*Meu desafio[^\n]*/i,/2\.\s*Demanda escolhida[^\n]*/i,{preserveLines:true});const secao2=between(text,/2\.\s*Demanda escolhida[^\n]*/i,/3\.\s*Criação e configuração[^\n]*/i,{preserveLines:true});const secao3=between(text,/3\.\s*Criação e configuração[^\n]*/i,/4\.\s*Testagem do agente[^\n]*/i,{preserveLines:true});const secao4=between(text,/4\.\s*Testagem do agente[^\n]*/i,/5\.\s*Análise dos testes[^\n]*/i,{preserveLines:true});const secao5=between(text,/5\.\s*Análise dos testes[^\n]*/i,/6\.\s*Contribuição do agente[^\n]*/i,{preserveLines:true});const secao6=between(text,/6\.\s*Contribuição do agente[^\n]*/i,/7\.\s*Transparência no uso de IA[^\n]*/i,{preserveLines:true});const secao7=between(text,/7\.\s*Transparência no uso de IA[^\n]*/i,/$/,{preserveLines:true});
  const ultimaPergunta=secao1.toLowerCase().lastIndexOf('como podemos');$('desafio').value=ultimaPergunta>=0?secao1.slice(ultimaPergunta).trim():secao1;
  $('demanda').value=between(secao2,/2\.1\s*Demanda escolhida[^\n]*/i,/2\.2\s*Público/i);$('publicoContexto').value=between(secao2,/2\.2\s*Público[^\n]*/i,/2\.3\s*Resultado/i);$('resultadoEsperado').value=stripFormPrompt(between(secao2,/2\.3\s*Resultado esperado[^\n]*/i,/$/),[/^O que o agente deverá entregar ou tornar possível\?\s*/i]);
  $('nomeGem').value=between(secao3,/3\.1\s*Nome do Gem/i,/3\.2\s*Descrição/i);$('descricaoGem').value=stripFormPrompt(between(secao3,/3\.2\s*Descrição[^\n]*/i,/3\.3\s*Instruções/i),[/^Copie a descrição cadastrada[^.]*\.\s*/i]);$('instrucoesGem').value=stripFormPrompt(between(secao3,/3\.3\s*Instruções[^\n]*/i,/3\.4\s*Ferramenta/i,{preserveLines:true}),[/^público, contexto, limites, tom e formato de resposta definidos\.\s*/i]);$('ferramentaPadrao').value=stripFormPrompt(between(secao3,/3\.4\s*Ferramenta padrão[^\n]*/i,/3\.5\s*Base de Conhecimento/i,{preserveLines:true}),[/^função no agente\.\s*/i]);$('fontesConhecimento').value=formatTableRows(between(secao3,/3\.5\s*Base de Conhecimento[^\n]*/i,/3\.6\s*Configurações/i,{preserveLines:true}));const blocoCitacoes=between(secao3,/Citações da Base de Conhecimento:/i,/Link de acesso ao Gem:/i,{preserveLines:true});$('citacoesStatus').value=/\(\s*[xX✓]\s*\)\s*Ativadas/i.test(blocoCitacoes)?'Ativadas':/\(\s*[xX✓]\s*\)\s*Desativadas/i.test(blocoCitacoes)?'Desativadas':'';$('citacoes').value=stripFormPrompt(blocoCitacoes,[/^\s*\([^\n]*?Justifique a escolha\.\s*/i]);$('outrasConfiguracoes').value=stripFormPrompt(between(secao3,/Outras decisões de configuração:/i,/$/,{preserveLines:true}),[/^Registre escolhas adicionais[^.]*\.\s*/i,/^compreender o funcionamento do agente\.\s*/i]);
  $('objetivoTeste').value=stripFormPrompt(between(secao4,/Objetivo do teste:/i,/Resultado esperado:/i,{preserveLines:true}),[/^O que você quis verificar\?\s*/i]).replace(/\s*●\s*$/,'').trim();$('resultadoEsperadoTeste').value=stripFormPrompt(between(secao4,/Resultado esperado:/i,/Captura de tela/i,{preserveLines:true}),[/^Como seria uma resposta satisfatória\?\s*O que você esperava\?\s*/i]);$('funcionouBem').value=stripFormPrompt(between(secao5,/O que funcionou bem\?/i,/O que ainda precisa melhorar\?/i,{preserveLines:true}),[/^Analise a utilidade, a qualidade, a clareza e a adequação das respostas à\s*/i,/^demanda escolhida\.\s*/i]);$('precisaMelhorar').value=stripFormPrompt(between(secao5,/O que ainda precisa melhorar\?/i,/Quais ajustes/i,{preserveLines:true}),[/^Identifique falhas, respostas inadequadas, lacunas nas fontes ou\s*/i,/^comportamentos inesperados\.\s*/i]);$('ajustes').value=stripFormPrompt(between(secao5,/Quais ajustes[^\n]*/i,/$/,{preserveLines:true}),[/^ferramentas ou demais configurações\.\s*/i]);$('contribuicao').value=stripFormPrompt(secao6,[/^Retome o desafio apresentado[\s\S]*?dessa contribuição\.\s*/i]);
  const gemLink=annotatedLinks.find(u=>/gemini\.google\.com|g\.co\/gemini/i.test(u))||simpleMatch(text,/(https?:\/\/\S+)/i);$('linkGem').value=gemLink||'';
  const sim=/Este trabalho teve uso de IA:\s*\(\s*[xX✓]\s*\)\s*Sim/i.test(secao7);const nao=/Este trabalho teve uso de IA:[^\n]*?Não\s*\(\s*[xX✓]\s*\)/i.test(secao7)||/Este trabalho teve uso de IA:[^\n]*?\(\s*[xX✓]\s*\)\s*Não/i.test(secao7);$('iaDeclaracao').value=sim?'Utilizou IA além do Gem':nao?'Não utilizou IA além do Gem':'';$('iaDescricao').value=stripFormPrompt(secao7,[/^Esta declaração se refere[\s\S]*?objeto da atividade\.\s*/i,/^Declaração de transparência no uso de IA \(além do GEM\)\s*/i,/^Este trabalho teve uso de IA:[^\n]*\n?\s*/i,/^Se sim, descreva[^:]*:\s*/i]);
}
function renderPageGallery(){$('pageGallery').innerHTML=pagePreviews.map((src,i)=>`<button type="button" class="page-thumb" data-page="${i}"><img src="${src}" alt="Miniatura da página ${i+1}"><span>Página ${i+1} · ampliar</span></button>`).join('');}
function openPage(index){$('modalTitle').textContent=`Página ${index+1} do relatório`;$('modalImage').src=pagePreviews[index];$('pageModal').classList.remove('hidden');document.body.style.overflow='hidden';}
function closePage(){$('pageModal').classList.add('hidden');$('modalImage').src='';document.body.style.overflow='';}
async function semanticExtract(){
  if(!rawPdfPages.length)return alert('Importe um PDF primeiro.');const b=$('semanticExtract');b.disabled=true;b.textContent='Interpretando...';$('pdfStatus').textContent='Separando semanticamente as respostas e a tabela...';
  try{const result=await api('/api/extrair-relatorio',{method:'POST',body:JSON.stringify({paginas:rawPdfPages,camposPreliminares:formData()})});for(const [key,val] of Object.entries(result)){if($(key)&&key!=='linkGem')$(key).value=val||'';}if(result.linkGem||!value('linkGem'))$('linkGem').value=result.linkGem||annotatedLinks.find(u=>/gemini\.google\.com|g\.co\/gemini/i.test(u))||'';$('pdfStatus').textContent='Interpretação semântica concluída. Revise os campos e confira visualmente as páginas/capturas.';checkDuplicate();renderAlerts();}
  catch(e){$('pdfStatus').textContent=`Não foi possível interpretar semanticamente: ${e.message}. Os campos preliminares permanecem disponíveis para revisão manual.`;}finally{b.disabled=false;b.textContent='Reinterpretar campos com IA';}
}
async function importPdf(file){
  if(!file)return;newEvaluation(false);$('pdfStatus').textContent='Lendo texto, tabela e páginas do PDF...';pdfImageCount=0;rawPdfPages=[];pagePreviews=[];annotatedLinks=[];structuredPageRows=[];$('semanticActions').classList.add('hidden');$('pageGallery').classList.add('hidden');
  try{
    const bytes=new Uint8Array(await file.arrayBuffer());const pdf=await pdfjsLib.getDocument({data:bytes}).promise;
    for(let i=1;i<=pdf.numPages;i++){const page=await pdf.getPage(i);const content=await page.getTextContent();const rows=layoutRows(content);structuredPageRows.push(rows);rawPdfPages.push(normalizePdfText(rows.map(rowText).join('\n')));const anns=await page.getAnnotations();anns.filter(a=>a.url).forEach(a=>annotatedLinks.push(a.url));const ops=await page.getOperatorList();pdfImageCount+=ops.fnArray.filter(fn=>fn===pdfjsLib.OPS.paintImageXObject||fn===pdfjsLib.OPS.paintJpegXObject).length;const viewport=page.getViewport({scale:1.25});const canvas=document.createElement('canvas');canvas.width=viewport.width;canvas.height=viewport.height;await page.render({canvasContext:canvas.getContext('2d'),viewport}).promise;pagePreviews.push(canvas.toDataURL('image/jpeg',.82));}
    const text=rawPdfPages.join('\n\n');applyPreliminaryExtraction(text,file.name);renderPageGallery();$('semanticActions').classList.remove('hidden');
    $('conformidadeModelo').value=`Arquivo PDF com ${pdf.numPages} página(s), estrutura do modelo P5 ${/Meu desafio/i.test(text)&&/Criação e configuração do Gem/i.test(text)?'identificada':'não confirmada'} e ${pdfImageCount} objeto(s) de imagem, incluindo elementos gráficos do próprio modelo. Revise a identificação, a estrutura e a legibilidade antes de pontuar.`;
    $('evidenciasTeste').value=pdfImageCount?`O PDF contém ${pdfImageCount} objeto(s) de imagem, incluindo elementos do modelo. Use “Ver páginas e capturas” para inspecionar visualmente a solicitação e a resposta do Gem; a contagem isolada não comprova evidência legível.`:'Nenhum objeto de imagem foi detectado automaticamente; confirme manualmente as evidências do teste.';
    $('imageCount').textContent=`Use “Ver páginas e capturas” para ampliar cada página. Foram detectados ${pdfImageCount} objeto(s) de imagem, incluindo elementos de layout.`;$('pdfStatus').textContent=`PDF lido: ${pdf.numPages} página(s). Iniciando interpretação semântica dos itens 3.3 a 7...`;checkDuplicate();updateScore();await semanticExtract();
  }catch(e){$('pdfStatus').textContent=`Falha ao ler o PDF: ${e.message}`;}
}

function evaluationId(){return currentEvaluationId||slug(value('matricula')||value('nome'))+'-'+Date.now();}
function snapshot(){const scores={};ORDER.forEach(k=>scores[k]={points:selected(k),observation:value(`obs_${k}`)});return {id:evaluationId(),...formData(),scores,manualAlerts:value('manualAlerts'),feedback:value('feedback'),agentAnalysis:value('agentAnalysis'),...(window.CoerenciaUI?CoerenciaUI.valores():{}),total:total(),updatedAt:new Date().toISOString()};}
function loadEvaluation(e){newEvaluation(false);currentEvaluationId=e.id;FIELD_IDS.forEach(id=>{if($(id))$(id).value=e[id]||'';});pdfImageCount=e.pdfImageCount||0;ORDER.forEach(k=>{if(e.scores?.[k]?.points!==null)setScore(k,e.scores[k].points);$(`obs_${k}`).value=e.scores?.[k]?.observation||'';});$('manualAlerts').value=e.manualAlerts||'';$('feedback').value=e.feedback||'';$('agentAnalysis').value=e.agentAnalysis||'';if(window.CoerenciaUI)CoerenciaUI.definir(e);updateScore();window.scrollTo({top:0,behavior:'smooth'});}
function newEvaluation(confirmFirst=true){if(confirmFirst&&!confirm('Limpar todo o formulário e iniciar nova avaliação?'))return;currentEvaluationId=null;FIELD_IDS.forEach(id=>{if($(id))$(id).value='';});ORDER.forEach(k=>{document.querySelectorAll(`input[name="rub_${k}"]`).forEach(x=>x.checked=false);$(`obs_${k}`).value='';});['manualAlerts','feedback','agentAnalysis'].forEach(id=>$(id).value='');if(window.CoerenciaUI)CoerenciaUI.limpar();['autoEvaluateStatus','agentAnalysisStatus','pdfStatus','imageCount','gemWindowStatus'].forEach(id=>$(id).textContent='');$('pdfFile').value='';$('pageGallery').innerHTML='';$('pageGallery').classList.add('hidden');$('semanticActions').classList.add('hidden');pdfImageCount=0;rawPdfPages=[];pagePreviews=[];annotatedLinks=[];structuredPageRows=[];closePage();checkDuplicate();updateScore();}
function checkDuplicate(){const n=value('nome').toLowerCase(),m=value('matricula').toLowerCase();const dup=evaluations.find(e=>e.id!==currentEvaluationId&&((m&&String(e.matricula||'').toLowerCase()===m)||(n&&String(e.nome||'').toLowerCase()===n)));$('nome').classList.toggle('duplicate',!!dup);$('matricula').classList.toggle('duplicate',!!dup);$('duplicidade').classList.toggle('hidden',!dup);$('duplicidade').textContent=dup?`Já existe avaliação para ${dup.nome||'este aluno'} nesta turma.`:'';}

async function loadClasses(preferred){try{classes=await api('/api/turmas');$('classSelect').innerHTML=classes.map(c=>`<option value="${escapeHtml(c.id)}">${escapeHtml(c.nome)} (${c.quantidade||0})</option>`).join('');if(preferred&&classes.some(c=>c.id===preferred))$('classSelect').value=preferred;if(classes.length){await loadEvaluations();const ativa=classes.find(c=>c.id===$('classSelect').value);$('classNameInput').value=ativa?.nome||'';}else{evaluations=[];$('classNameInput').value='';renderRoster();$('classStatus').textContent='Crie uma turma para começar.';}}catch(e){$('classStatus').textContent=e.message;}}
async function loadEvaluations(){const id=$('classSelect').value;if(!id)return;evaluations=await api(`/api/turmas/${encodeURIComponent(id)}/avaliacoes`);renderRoster();checkDuplicate();}
function renderRoster(){$('roster').innerHTML=evaluations.length?evaluations.map(e=>`<tr><td>${escapeHtml(e.nome||'Sem nome')}</td><td>${escapeHtml(e.matricula||'—')}</td><td>${Number(e.total||0).toLocaleString('pt-BR')}</td><td><button class="btn secondary" data-open="${escapeHtml(e.id)}">Abrir</button><button class="btn danger" data-delete="${escapeHtml(e.id)}">Excluir</button></td></tr>`).join(''):'<tr><td colspan="4">Nenhum aluno salvo.</td></tr>';}
function sameStudent(e){const m=value('matricula').toLowerCase(),n=value('nome').toLowerCase(),em=String(e?.matricula||'').trim().toLowerCase(),en=String(e?.nome||'').trim().toLowerCase();return m&&em?m===em:Boolean(n&&en&&n===en);}
async function saveEvaluation(){const cid=$('classSelect').value;if(!cid){$('classStatus').textContent='Crie ou selecione uma turma antes de salvar o aluno.';return;}if(!value('nome')&&!value('matricula')){$('classStatus').textContent='Informe o nome ou a matrícula do aluno.';return;}try{const aberto=evaluations.find(e=>e.id===currentEvaluationId);const novaIdentidade=Boolean(aberto&&!sameStudent(aberto));if(novaIdentidade)currentEvaluationId=null;const data=snapshot();await api(`/api/turmas/${encodeURIComponent(cid)}/avaliacoes/${encodeURIComponent(data.id)}`,{method:'PUT',body:JSON.stringify(data)});currentEvaluationId=data.id;await loadClasses(cid);$('classStatus').textContent=`${novaIdentidade?'Nova avaliação':'Avaliação'} salva com sucesso para ${data.nome||data.matricula}.`;}catch(e){$('classStatus').textContent=`Não foi possível salvar: ${e.message}`;}}

function download(name,content,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();URL.revokeObjectURL(a.href);}
function exportJson(){const c=classes.find(x=>x.id===$('classSelect').value);download(`${slug(c?.nome)}-p5.json`,JSON.stringify({version:2,turma:c,avaliacoes:evaluations},null,2));}
function csvCell(v){return `"${String(v??'').replace(/"/g,'""')}"`;}
function exportCsv(){const header=['Nome','Matrícula','Nota',...ORDER.map(k=>RUBRIC[k].label),'Alertas'];const rows=evaluations.map(e=>[e.nome,e.matricula,e.total,...ORDER.map(k=>e.scores?.[k]?.points??''),e.manualAlerts]);download('avaliacoes-p5.csv',[header,...rows].map(r=>r.map(csvCell).join(';')).join('\n'),'text/csv;charset=utf-8');}

function executiveReportLegacy(){
  if(!evaluations.length)return alert('A turma não possui avaliações.');const c=classes.find(x=>x.id===$('classSelect').value);const avg=evaluations.reduce((n,e)=>n+Number(e.total||0),0)/evaluations.length;const dist=[0,0,0,0];evaluations.forEach(e=>dist[e.total>=9?3:e.total>=7?2:e.total>=5?1:0]++);const criteria=ORDER.map(k=>{const vals=evaluations.map(e=>Number(e.scores?.[k]?.points)).filter(Number.isFinite);const mean=vals.reduce((a,b)=>a+b,0)/(vals.length||1);return {k,mean,pct:Math.round(mean/RUBRIC[k].max*100)};});const weak=[...criteria].sort((a,b)=>a.pct-b.pct).slice(0,3);const alerts=evaluations.flatMap(e=>String(e.manualAlerts||'').split('\n')).map(s=>s.trim()).filter(Boolean);const topAlerts=Object.entries(alerts.reduce((m,a)=>(m[a]=(m[a]||0)+1,m),{})).sort((a,b)=>b[1]-a[1]).slice(0,5);
  const html=`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Relatório executivo P5</title><style>@page{margin:18mm}body{font-family:Arial;color:#20343a;margin:0}header{background:#174f5a;color:white;padding:28px;border-radius:14px}h1{margin:0;font-size:26px}h2{color:#174f5a;border-bottom:2px solid #dff1f2;padding-bottom:7px;margin-top:28px}.meta{opacity:.85;margin-top:6px}.kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:18px 0}.kpi{border:1px solid #ccd8dc;border-radius:10px;padding:16px}.kpi strong{display:block;font-size:27px;color:#1f7583}.bar{height:18px;background:#e9eff0;border-radius:9px;overflow:hidden}.bar i{display:block;height:100%;background:#1f7583}.row{display:grid;grid-template-columns:280px 1fr 55px;gap:10px;align-items:center;margin:10px 0;font-size:13px}.cards{display:grid;grid-template-columns:1fr 1fr;gap:14px}.card{border:1px solid #ccd8dc;border-radius:10px;padding:15px}.student{width:100%;border-collapse:collapse;font-size:12px}.student th{background:#174f5a;color:white}.student th,.student td{padding:7px;border:1px solid #dbe3e5;text-align:left}.note{background:#fff6df;border-left:4px solid #d89b2b;padding:12px}button{padding:10px 15px;background:#174f5a;color:white;border:0;border-radius:6px}@media print{button{display:none}}</style></head><body><header><h1>Relatório Executivo · P5 Agente de IA</h1><div class="meta">${escapeHtml(c?.nome||'Turma')} · ${new Date().toLocaleDateString('pt-BR')}</div></header><div class="kpis"><div class="kpi"><strong>${evaluations.length}</strong>avaliações</div><div class="kpi"><strong>${avg.toFixed(1)}</strong>média da turma</div><div class="kpi"><strong>${Math.min(...evaluations.map(e=>e.total)).toFixed(1)}–${Math.max(...evaluations.map(e=>e.total)).toFixed(1)}</strong>amplitude</div></div><h2>Desempenho por critério</h2>${criteria.map(x=>`<div class="row"><span>${escapeHtml(RUBRIC[x.k].label)}</span><div class="bar"><i style="width:${x.pct}%"></i></div><b>${x.pct}%</b></div>`).join('')}<h2>Distribuição das notas</h2><div class="cards">${['Abaixo de 5','5 a 6,9','7 a 8,9','9 a 10'].map((x,i)=>`<div class="card"><b>${x}</b><div style="font-size:25px;color:#1f7583">${dist[i]}</div></div>`).join('')}</div><h2>Insights pedagógicos</h2><div class="note"><b>Prioridades para a próxima oferta</b><p>Os critérios com menor desempenho relativo foram ${weak.map(x=>`${RUBRIC[x.k].label} (${x.pct}%)`).join(', ')}. Recomenda-se tornar mais explícitos no enunciado e no modelo os exemplos de evidência esperada para esses pontos.</p></div>${topAlerts.length?`<h3>Alertas recorrentes</h3><ul>${topAlerts.map(([a,n])=>`<li>${escapeHtml(a)} <b>(${n})</b></li>`).join('')}</ul>`:''}<h2>Resultados individuais</h2><table class="student"><thead><tr><th>Aluno</th><th>Matrícula</th><th>Nota</th></tr></thead><tbody>${evaluations.sort((a,b)=>String(a.nome).localeCompare(String(b.nome))).map(e=>`<tr><td>${escapeHtml(e.nome)}</td><td>${escapeHtml(e.matricula)}</td><td>${Number(e.total).toFixed(1)}</td></tr>`).join('')}</tbody></table><h2>Sugestões de melhoria da aula e das instruções</h2><ol><li>Apresentar um exemplo curto de instruções completas, destacando papel, tarefas, público, contexto, limites, tom e formato.</li><li>Mostrar como registrar fontes pela função que cumprem, e não apenas pelo nome do arquivo.</li><li>Demonstrar um teste realista com objetivo, resposta satisfatória e evidências legíveis.</li><li>Explicitar a diferença entre criar/testar o Gem e usar outra IA para redigir o relatório.</li><li>Reservar tempo para transformar falhas observadas em ajustes concretos e retestar.</li></ol><p><button onclick="print()">Imprimir / salvar em PDF</button></p></body></html>`;const w=window.open('','_blank');w.document.write(html);w.document.close();}

function executiveReport(){
  if(!evaluations.length)return alert('A turma não possui avaliações.');

  const turma=classes.find(x=>x.id===$('classSelect').value);
  const temNota=v=>v!==null&&v!==undefined&&v!==''&&Number.isFinite(Number(v));
  const notas=evaluations.map(e=>Number(e.total)).filter(Number.isFinite);
  const media=notas.reduce((a,b)=>a+b,0)/(notas.length||1);
  const ordenadas=[...notas].sort((a,b)=>a-b);
  const meio=Math.floor(ordenadas.length/2);
  const mediana=ordenadas.length%2?ordenadas[meio]:(ordenadas[meio-1]+ordenadas[meio])/2;
  const minimo=Math.min(...notas),maximo=Math.max(...notas);
  const faixas=[
    {label:'Abaixo de 6,0',count:notas.filter(n=>n<6).length,color:'#b6473f'},
    {label:'6,0 a 7,9',count:notas.filter(n=>n>=6&&n<8).length,color:'#d39a2c'},
    {label:'8,0 a 8,9',count:notas.filter(n=>n>=8&&n<9).length,color:'#4f94a0'},
    {label:'9,0 a 10,0',count:notas.filter(n=>n>=9).length,color:'#28735e'}
  ];
  const criterios=ORDER.map(k=>{
    const valores=evaluations.map(e=>e.scores?.[k]?.points).filter(temNota).map(Number);
    const mediaCriterio=valores.reduce((a,b)=>a+b,0)/(valores.length||1);
    return {k,label:RUBRIC[k].label,max:RUBRIC[k].max,media:mediaCriterio,pct:Math.round((mediaCriterio/RUBRIC[k].max)*100),respondidos:valores.length};
  });
  const completos=evaluations.filter(e=>ORDER.every(k=>temNota(e.scores?.[k]?.points))).length;
  const pendentes=evaluations.length-completos;
  const conclusao=Math.round((completos/evaluations.length)*100);
  const acessoConfirmado=evaluations.filter(e=>String(e.linkVerificado||'').startsWith('Sim')).length;
  const acessoFalhou=evaluations.filter(e=>String(e.linkVerificado||'').includes('Não foi possível')).length;
  const acessoPct=Math.round((acessoConfirmado/evaluations.length)*100);
  const iaAdicional=evaluations.filter(e=>String(e.iaDeclaracao||'').startsWith('Utilizou')).length;
  const alertas=evaluations.flatMap(e=>String(e.manualAlerts||'').split('\n')).map(s=>s.trim()).filter(Boolean);
  const alertasPrincipais=Object.entries(alertas.reduce((acc,a)=>(acc[a]=(acc[a]||0)+1,acc),{})).sort((a,b)=>b[1]-a[1]).slice(0,6);
  const ranking=[...criterios].sort((a,b)=>b.pct-a.pct);
  const forte=ranking[0],fragil=[...ranking].reverse()[0];
  const pct=n=>Math.round((n/evaluations.length)*100);
  const diagnostico=media>=9?'desempenho geral excelente':media>=8?'desempenho geral muito bom':media>=6?'desempenho geral satisfatório, com oportunidades claras de consolidação':'desempenho geral abaixo do esperado, indicando necessidade de intervenção pedagógica';
  const recomendacoes=[];
  const orientacoes={
    modelo:'Reforçar o uso integral do modelo obrigatório e a conferência dos dados de identificação antes da entrega.',
    demanda:'Incluir um exemplo que conecte pergunta-desafio, demanda, público, contexto e resultado esperado.',
    configuracao:'Disponibilizar um exemplo comentado de configuração completa: instruções integrais, funções das fontes, citações, decisões e link público.',
    testagem:'Demonstrar um teste realista com objetivo, resultado esperado e capturas legíveis contendo solicitação e resposta.',
    analise:'Orientar a análise a relacionar evidências dos testes, falhas encontradas, ajustes concretos e uma nova rodada de validação.',
    contribuicao:'Explicitar que a contribuição deve indicar a parte do desafio apoiada, os beneficiários e os limites do agente.',
    transparencia:'Diferenciar claramente a criação do Gem do uso de outras ferramentas de IA para elaborar o relatório.'
  };
  recomendacoes.push(orientacoes[fragil.k]);
  if(acessoConfirmado<evaluations.length)recomendacoes.push('Criar uma etapa final de conferência do compartilhamento público, preferencialmente em janela anônima e antes do envio do PDF.');
  if(criterios.find(c=>c.k==='testagem').pct<80)recomendacoes.push(orientacoes.testagem);
  if(criterios.find(c=>c.k==='analise').pct<80)recomendacoes.push(orientacoes.analise);
  if(pendentes)recomendacoes.push(`Concluir os critérios pendentes em ${pendentes} avaliação${pendentes===1?'':'ões'} antes de tomar decisões definitivas sobre a turma.`);
  recomendacoes.push('Reservar tempo de aula para testar, interpretar os resultados, ajustar o agente e retestar; o refinamento deve aparecer como parte do processo, não apenas como intenção futura.');
  const unicas=[...new Set(recomendacoes)].slice(0,5);
  const data=new Date().toLocaleDateString('pt-BR',{day:'2-digit',month:'long',year:'numeric'});
  const linhas=[...evaluations].sort((a,b)=>Number(b.total||0)-Number(a.total||0)||String(a.nome||'').localeCompare(String(b.nome||''),'pt-BR'));

  const html=`<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Relatório Executivo · P5 Agente de IA</title><style>
  :root{--navy:#123f48;--teal:#217684;--teal2:#4d9aa5;--pale:#e8f3f4;--ink:#20343a;--muted:#61747a;--line:#d6e1e3;--gold:#d89b2b;--red:#b6473f;--green:#28735e}*{box-sizing:border-box}body{margin:0;background:#edf2f3;color:var(--ink);font:15px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif}.page{width:min(1000px,calc(100% - 30px));margin:28px auto;background:#fff;box-shadow:0 12px 42px #173b4526}.hero{position:relative;overflow:hidden;padding:46px 54px 38px;background:linear-gradient(125deg,#123f48 0%,#1b6571 70%,#278291 100%);color:#fff}.hero:after{content:"";position:absolute;width:300px;height:300px;border:60px solid #ffffff12;border-radius:50%;right:-105px;top:-135px}.brand{display:flex;align-items:center;gap:18px;position:relative;z-index:1}.brand img{width:76px;height:76px;object-fit:contain;filter:drop-shadow(0 5px 10px #0b293555)}.eyebrow{text-transform:uppercase;letter-spacing:.15em;font-weight:800;font-size:11px;color:#bce3e8}.hero h1{font-size:34px;line-height:1.12;margin:5px 0 8px}.hero p{margin:0;color:#d9eef1}.hero-meta{position:relative;z-index:1;display:flex;flex-wrap:wrap;gap:22px;margin-top:27px;padding-top:18px;border-top:1px solid #ffffff38;font-size:13px}.content{padding:40px 54px 55px}.section{margin:0 0 38px}.section h2{margin:0 0 17px;color:var(--navy);font-size:21px;display:flex;gap:10px;align-items:center}.section h2 span{display:grid;place-items:center;width:28px;height:28px;border-radius:50%;background:var(--pale);color:var(--teal);font-size:13px}.lead{font-size:16px;margin:0}.summary{padding:22px 24px;background:linear-gradient(90deg,#eaf5f5,#f7faf9);border-left:5px solid var(--teal);border-radius:0 10px 10px 0}.summary strong{color:var(--navy)}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:13px}.kpi{border:1px solid var(--line);border-radius:12px;padding:18px;background:#fff}.kpi small{display:block;color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.06em;font-weight:700}.kpi strong{display:block;color:var(--teal);font-size:29px;line-height:1.15;margin:6px 0}.kpi em{font-style:normal;color:var(--muted);font-size:12px}.criterion{display:grid;grid-template-columns:minmax(230px,1.45fr) 2fr 70px;gap:14px;align-items:center;padding:9px 0}.criterion-name{font-size:13px}.track{height:12px;background:#e7edef;border-radius:8px;overflow:hidden}.fill{height:100%;border-radius:8px;background:linear-gradient(90deg,var(--teal),var(--teal2))}.criterion b{text-align:right;color:var(--navy);font-size:13px}.criterion b small{display:block;color:var(--muted);font-weight:500}.split{display:grid;grid-template-columns:1fr 1fr;gap:18px}.card{border:1px solid var(--line);border-radius:12px;padding:20px}.card h3{margin:0 0 13px;color:var(--navy);font-size:16px}.bands{display:flex;align-items:flex-end;height:155px;gap:12px;padding-top:12px}.band{flex:1;text-align:center;color:var(--muted);font-size:10px}.column{min-height:5px;border-radius:7px 7px 0 0;margin-bottom:6px}.band b{display:block;color:var(--navy);font-size:17px}.fact{display:flex;justify-content:space-between;gap:12px;padding:9px 0;border-bottom:1px solid #e8edef}.fact:last-child{border:0}.fact strong{color:var(--navy)}.callout{padding:18px 20px;border-radius:10px;background:#fff7e6;border-left:5px solid var(--gold)}.callout p{margin:5px 0 0}.alerts{margin:0;padding-left:20px}.alerts li{margin:8px 0}.alerts b{color:var(--red)}.recommendations{counter-reset:item;list-style:none;padding:0;margin:0}.recommendations li{counter-increment:item;position:relative;padding:0 0 15px 44px;min-height:34px}.recommendations li:before{content:counter(item);position:absolute;left:0;top:0;display:grid;place-items:center;width:29px;height:29px;background:var(--navy);color:#fff;border-radius:50%;font-weight:800;font-size:12px}table{border-collapse:collapse;width:100%;font-size:12px}thead{display:table-header-group}th{background:var(--navy);color:#fff;text-align:left;padding:10px}td{border-bottom:1px solid var(--line);padding:9px 10px}tbody tr:nth-child(even){background:#f7f9f9}.score{font-weight:800;color:var(--navy)}.status{display:inline-block;border-radius:12px;padding:2px 8px;font-size:10px;font-weight:700}.ok{background:#dff1e9;color:#1f644f}.warn{background:#fff0d0;color:#875e0f}.no{background:#f8dfdc;color:#8d3933}.method{color:var(--muted);font-size:12px;border-top:1px solid var(--line);padding-top:18px}.print{position:fixed;right:25px;bottom:25px;border:0;border-radius:24px;background:var(--gold);color:#172e34;padding:13px 20px;font-weight:800;box-shadow:0 5px 18px #0003;cursor:pointer}@media(max-width:720px){.hero,.content{padding-left:24px;padding-right:24px}.hero h1{font-size:27px}.kpis{grid-template-columns:1fr 1fr}.split{grid-template-columns:1fr}.criterion{grid-template-columns:1fr 75px}.criterion .track{grid-column:1/-1;grid-row:2}.brand img{width:60px;height:60px}}@media print{@page{size:A4;margin:13mm}body{background:#fff;font-size:11px}.page{width:auto;margin:0;box-shadow:none}.hero{padding:25px 30px 22px;-webkit-print-color-adjust:exact;print-color-adjust:exact}.hero h1{font-size:25px}.brand img{width:54px;height:54px}.hero-meta{margin-top:16px;padding-top:10px}.content{padding:25px 30px}.section{margin-bottom:24px}.section h2{font-size:17px;margin-bottom:12px}.kpi,.card,.summary,.callout,.criterion,.recommendations li,tr{break-inside:avoid}.kpi{padding:12px}.kpi strong{font-size:22px}.bands{height:115px}.print{display:none}.section.page-break{break-before:page}table{font-size:9px}th,td{padding:6px}}
  </style></head><body><main class="page"><header class="hero"><div class="brand"><img src="${location.origin}/assets/logo-ai-agent.png" alt="Agente de IA"><div><div class="eyebrow">Especialização em Tecnologias para Educação Profissional e Tecnológica</div><h1>Relatório Executivo · P5 Agente de IA</h1><p>Avaliação da criação, testagem e análise crítica de um agente inteligente</p></div></div><div class="hero-meta"><span><b>Turma:</b> ${escapeHtml(turma?.nome||'Não identificada')}</span><span><b>Emissão:</b> ${data}</span><span><b>Avaliações:</b> ${evaluations.length}</span></div></header><div class="content">
  <section class="section"><h2><span>1</span> Síntese executiva</h2><div class="summary"><p class="lead">A turma apresentou <strong>${diagnostico}</strong>, com média <strong>${media.toFixed(1).replace('.',',')}</strong> e mediana <strong>${mediana.toFixed(1).replace('.',',')}</strong>. As notas variaram de <strong>${minimo.toFixed(1).replace('.',',')}</strong> a <strong>${maximo.toFixed(1).replace('.',',')}</strong>.</p><p>O melhor resultado proporcional ocorreu em <strong>${escapeHtml(forte.label)}</strong> (${forte.pct}%), enquanto <strong>${escapeHtml(fragil.label)}</strong> (${fragil.pct}%) demanda maior atenção. O acesso público ao agente foi confirmado em ${acessoConfirmado} de ${evaluations.length} trabalhos; em ${acessoFalhou}, não foi possível validar a publicação.</p></div></section>
  <section class="section"><h2><span>2</span> Indicadores principais</h2><div class="kpis"><div class="kpi"><small>Avaliações</small><strong>${evaluations.length}</strong><em>registros na turma</em></div><div class="kpi"><small>Média geral</small><strong>${media.toFixed(1).replace('.',',')}</strong><em>em uma escala de 0 a 10</em></div><div class="kpi"><small>Avaliações completas</small><strong>${conclusao}%</strong><em>${completos} completas · ${pendentes} pendentes</em></div><div class="kpi"><small>Acesso público validado</small><strong>${acessoPct}%</strong><em>${acessoConfirmado} agentes acessíveis</em></div></div></section>
  <section class="section"><h2><span>3</span> Desempenho por critério</h2>${criterios.map(c=>`<div class="criterion"><div class="criterion-name">${escapeHtml(c.label)}</div><div class="track"><div class="fill" style="width:${Math.max(0,Math.min(100,c.pct))}%"></div></div><b>${c.pct}%<small>${c.media.toFixed(2).replace('.',',')} / ${c.max}</small></b></div>`).join('')}</section>
  <section class="section"><h2><span>4</span> Distribuição e contexto</h2><div class="split"><div class="card"><h3>Distribuição das notas</h3><div class="bands">${faixas.map(f=>`<div class="band"><div class="column" style="height:${Math.max(5,pct(f.count))}%;background:${f.color}"></div><b>${f.count}</b>${f.label}</div>`).join('')}</div></div><div class="card"><h3>Leitura complementar</h3><div class="fact"><span>Mediana da turma</span><strong>${mediana.toFixed(1).replace('.',',')}</strong></div><div class="fact"><span>Amplitude das notas</span><strong>${(maximo-minimo).toFixed(1).replace('.',',')} pontos</strong></div><div class="fact"><span>Agentes sem acesso público confirmado</span><strong>${evaluations.length-acessoConfirmado}</strong></div><div class="fact"><span>Uso declarado de IA além do Gem</span><strong>${iaAdicional} (${pct(iaAdicional)}%)</strong></div></div></div></section>
  <section class="section"><h2><span>5</span> Padrões e alertas</h2><div class="callout"><strong>Leitura pedagógica</strong><p>Os indicadores automatizados apoiam a visão de conjunto, mas não substituem a revisão docente do PDF, das capturas de tela, do link publicado e da coerência entre a testagem relatada e a análise crítica do estudante.</p></div>${alertasPrincipais.length?`<h3 style="margin-top:20px">Alertas recorrentes registrados</h3><ul class="alerts">${alertasPrincipais.map(([a,n])=>`<li>${escapeHtml(a)} <b>${n} ocorrência${n===1?'':'s'}</b></li>`).join('')}</ul>`:'<p style="color:var(--muted)">Não há alertas recorrentes registrados nesta turma.</p>'}</section>
  <section class="section"><h2><span>6</span> Recomendações para a próxima oferta</h2><ol class="recommendations">${unicas.map(r=>`<li>${escapeHtml(r)}</li>`).join('')}</ol></section>
  <section class="section page-break"><h2><span>7</span> Resultados individuais</h2><table><thead><tr><th>#</th><th>Aluno</th><th>Matrícula</th><th>Nota</th><th>Acesso ao agente</th><th>Avaliação</th></tr></thead><tbody>${linhas.map((e,i)=>{const completo=ORDER.every(k=>temNota(e.scores?.[k]?.points));const acesso=String(e.linkVerificado||'');const classe=acesso.startsWith('Sim')?'ok':acesso.includes('Não foi possível')?'no':'warn';const texto=acesso.startsWith('Sim')?'Validado':acesso.includes('Não foi possível')?'Inacessível':'Não verificado';return `<tr><td>${i+1}</td><td>${escapeHtml(e.nome||'Sem nome')}</td><td>${escapeHtml(e.matricula||'—')}</td><td class="score">${Number(e.total||0).toFixed(1).replace('.',',')}</td><td><span class="status ${classe}">${texto}</span></td><td><span class="status ${completo?'ok':'warn'}">${completo?'Completa':'Pendente'}</span></td></tr>`}).join('')}</tbody></table></section>
  <section class="section"><h2><span>8</span> Nota metodológica</h2><p class="method">Este relatório consolida as avaliações salvas no aplicativo na data de emissão. Os percentuais por critério representam a média obtida em relação à pontuação máxima do respectivo critério. Alertas e observações refletem os registros existentes e podem ser alterados pelo avaliador. A interpretação pedagógica deve considerar o tamanho da turma, a completude das avaliações e a verificação qualitativa dos trabalhos.</p></section>
  </div></main><button class="print" onclick="window.print()">Imprimir / salvar em PDF</button></body></html>`;
  const w=window.open('','_blank');
  if(!w)return alert('O navegador bloqueou a abertura do relatório. Permita janelas pop-up para este site e tente novamente.');
  w.document.open();w.document.write(html);w.document.close();
}

async function importClassJson(file){
  if(!file)return;
  const status=$('importStatus');status.textContent='Lendo e importando o arquivo...';
  try{
    const obj=JSON.parse(await file.text());
    const items=Array.isArray(obj)?obj:(Array.isArray(obj.avaliacoes)?obj.avaliacoes:[obj]);
    if(!items.length)throw new Error('O arquivo não contém avaliações.');
    const turma=obj.turma?.nome?obj.turma:classes.find(c=>c.id===$('classSelect').value);
    if(!turma)throw new Error('Este JSON não informa a turma. Crie ou selecione uma turma antes de importá-lo.');
    const body=JSON.stringify({turma,avaliacoes:items});
    let resultado;
    try{resultado=await api('/api/importar-turma',{method:'POST',body});}
    catch(err){
      if(!/Failed to fetch|Falha de rede|NetworkError/i.test(err.message))throw err;
      status.textContent='A conexão oscilou. Tentando novamente...';
      await new Promise(resolve=>setTimeout(resolve,1800));
      resultado=await api('/api/importar-turma',{method:'POST',body});
    }
    await loadClasses(resultado.id);
    status.textContent=`Importação concluída: ${resultado.inseridas} nova(s), ${resultado.atualizadas} atualizada(s). Turma ${resultado.nome}: ${resultado.quantidade} avaliação(ões).`;
    $('classStatus').textContent=`Turma ${resultado.nome} carregada com ${resultado.quantidade} avaliação(ões).`;
  }catch(err){status.textContent=/Failed to fetch/i.test(err.message)?'O servidor não respondeu. Aguarde alguns segundos e tente novamente; o arquivo não foi alterado.':`Não foi possível importar: ${err.message}`;}
  finally{$('importJson').value='';}
}

function bind(){
  $('pdfFile').addEventListener('change',e=>importPdf(e.target.files[0]));FIELD_IDS.forEach(id=>{$(id)?.addEventListener('input',()=>{if(id==='nome'||id==='matricula')checkDuplicate();if(id==='linkGem')$('gemWindowStatus').textContent='';renderAlerts();});});$('linkVerificado').addEventListener('change',renderAlerts);$('manualAlerts').addEventListener('input',renderAlerts);$('openGem').onclick=openGem;$('copyGemLink').onclick=async()=>{const url=validExternalUrl(value('linkGem'));if(!url)return $('gemWindowStatus').textContent='Informe um link válido antes de copiar.';await navigator.clipboard.writeText(url.href);$('gemWindowStatus').textContent='Link copiado.';};
  $('semanticExtract').onclick=semanticExtract;$('togglePages').onclick=()=>{$('pageGallery').classList.toggle('hidden');$('togglePages').textContent=$('pageGallery').classList.contains('hidden')?'Ver páginas e capturas':'Ocultar páginas';};$('pageGallery').onclick=e=>{const button=e.target.closest('[data-page]');if(button)openPage(Number(button.dataset.page));};$('closeModal').onclick=closePage;$('pageModal').onclick=e=>{if(e.target===$('pageModal'))closePage();};document.addEventListener('keydown',e=>{if(e.key==='Escape')closePage();});
  $('autoEvaluate').onclick=autoEvaluate;$('analyzeAgent').onclick=analyzeAgent;$('refreshFeedback').onclick=()=>generateLocalFeedback(true);$('copyFeedback').onclick=()=>navigator.clipboard.writeText(value('feedback'));$('copyAnalysis').onclick=()=>navigator.clipboard.writeText(value('agentAnalysis'));$('clearRubric').onclick=()=>{ORDER.forEach(k=>{document.querySelectorAll(`input[name="rub_${k}"]`).forEach(x=>x.checked=false);$(`obs_${k}`).value='';});updateScore();};
  $('classSelect').onchange=async()=>{await loadEvaluations();const c=classes.find(x=>x.id===$('classSelect').value);$('classNameInput').value=c?.nome||'';$('classStatus').textContent='';};$('refreshClasses').onclick=async()=>{const atual=$('classSelect').value;$('classStatus').textContent='Atualizando turmas...';await loadClasses(atual);$('classStatus').textContent=classes.length?`${classes.length} turma(s) carregada(s) do banco.`:'Nenhuma turma encontrada no banco.';};$('newClass').onclick=async()=>{const n=value('classNameInput');if(!n){$('classStatus').textContent='Digite o nome da nova turma no campo acima.';return;}try{const c=await api('/api/turmas',{method:'POST',body:JSON.stringify({nome:n})});await loadClasses(c.id);$('classNameInput').value=c.nome;$('classStatus').textContent='Turma criada com sucesso.';}catch(e){$('classStatus').textContent=`Não foi possível criar a turma: ${e.message}`;}};$('renameClass').onclick=async()=>{const c=classes.find(x=>x.id===$('classSelect').value),n=value('classNameInput');if(!c){$('classStatus').textContent='Selecione uma turma.';return;}if(!n){$('classStatus').textContent='Digite o novo nome da turma.';return;}try{await api(`/api/turmas/${encodeURIComponent(c.id)}`,{method:'PATCH',body:JSON.stringify({nome:n})});await loadClasses(c.id);$('classStatus').textContent='Turma renomeada com sucesso.';}catch(e){$('classStatus').textContent=`Não foi possível renomear: ${e.message}`;}};$('deleteClass').onclick=async()=>{const c=classes.find(x=>x.id===$('classSelect').value),confirmName=value('classNameInput');if(!c){$('classStatus').textContent='Selecione uma turma.';return;}if(confirmName!==c.nome){$('classStatus').textContent=`Para excluir, digite exatamente: ${c.nome}`;return;}try{await api(`/api/turmas/${encodeURIComponent(c.id)}`,{method:'DELETE',body:JSON.stringify({confirmarNome:confirmName})});newEvaluation(false);$('classNameInput').value='';await loadClasses();$('classStatus').textContent='Turma excluída.';}catch(e){$('classStatus').textContent=`Não foi possível excluir: ${e.message}`;}};
  $('saveEvaluation').onclick=saveEvaluation;$('newEvaluation').onclick=()=>newEvaluation(true);$('exportJson').onclick=exportJson;$('exportCsv').onclick=exportCsv;$('executiveReport').onclick=executiveReport;$('githubBackup').onclick=async()=>{try{const r=await api('/api/backup/github',{method:'POST'});$('classStatus').textContent=r.ultimoErro?`Falha: ${r.ultimoErro}`:`Cópia no GitHub atualizada em ${new Date(r.ultimaSincronizacao).toLocaleString('pt-BR')}.`;}catch(e){$('classStatus').textContent=e.message;}};$('clearClass').onclick=async()=>{const c=classes.find(x=>x.id===$('classSelect').value);if(c&&confirm(`Apagar TODAS as avaliações de ${c.nome}?`)){await api(`/api/turmas/${encodeURIComponent(c.id)}/avaliacoes`,{method:'DELETE'});newEvaluation(false);await loadClasses(c.id);}};
  $('roster').onclick=async e=>{const open=e.target.dataset.open,del=e.target.dataset.delete;if(open)loadEvaluation(evaluations.find(x=>x.id===open));if(del&&confirm('Excluir esta avaliação?')){await api(`/api/turmas/${encodeURIComponent($('classSelect').value)}/avaliacoes/${encodeURIComponent(del)}`,{method:'DELETE'});await loadClasses($('classSelect').value);}};
  $('chooseImportJson').onclick=()=>$('importJson').click();$('importJson').onchange=e=>importClassJson(e.target.files[0]);
}

document.addEventListener('DOMContentLoaded',async()=>{pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';renderRubric();bind();updateScore();try{const q=new URLSearchParams(location.search),tq=q.get('turma'),aq=q.get('avaliacao');await loadClasses(tq||undefined);if(aq){const e=evaluations.find(x=>x.id===aq);if(e){loadEvaluation(e);$('classStatus').textContent='Avaliação aberta pelo link do Fechamento do Portfólio.';}else $('classStatus').textContent='A avaliação indicada no link não foi encontrada nesta turma.';}}catch{}if('serviceWorker'in navigator)navigator.serviceWorker.register('/service-worker.js').catch(()=>{});});
